// ── Generation logic ──
function deepTranslate(enObj, dict) {
  if (typeof enObj === 'string') return dict[enObj] || enObj;
  if (Array.isArray(enObj)) return enObj.map(v => deepTranslate(v, dict));
  if (enObj && typeof enObj === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(enObj)) out[k] = deepTranslate(v, dict);
    return out;
  }
  return enObj;
}

for (const ns of NS) {
  const enPath = path.join(BASE, `${ns}.json`);
  const enData = JSON.parse(fs.readFileSync(enPath, 'utf8'));
  for (const lang of LANGS) {
    const outDir = path.join(OUT, lang);
    mkdir(outDir);
    const dict = (D[ns] && D[ns][lang]) || {};
    const translated = deepTranslate(enData, dict);
    fs.writeFileSync(path.join(outDir, `${ns}.json`), JSON.stringify(translated, null, 2) + '\n');
  }
}

console.log(`Generated ${LANGS.length} languages × ${NS.length} namespaces = ${LANGS.length * NS.length} files in ${OUT}`);
